 host.querySelectorAll('[data-change-summary]').forEach(el=>el.oninput=()=>bundle().summary=el.value);host.querySelectorAll('[data-config-summary]').forEach(el=>el.oninput=()=>state.configSummary=el.value);host.querySelectorAll('[data-gs-fail]').forEach(el=>el.onchange=()=>state.fail=el.checked);
